class TrafficLight {
  private int green = 1; // road A starts green

  public TrafficLight() {}

  // one car at a time: switch the light only when this car's road is red, then cross
  public synchronized void carArrived(int carId, int roadId, int direction, Runnable turnGreen, Runnable crossCar) {
    if (roadId != green) {
      turnGreen.run();
      green = roadId;
    }
    crossCar.run();
  }
}
